package stats

import (
	"fmt"
	"math"
)

// Timing v2 (c2parser v8, "-timing v2"). Spec: claude/v8-engineering-prompt.md
// Q2, research/C2 timing threshold validation.md §3, §6, §8.
//
// Design rules carried over from the research:
//   - Dispersion (CV / Kim–Jo A_n) is the jitter-robust *detector*.
//   - Harmonic concentration R_h, absolute phase R_a, polarity, spread and
//     the integer-second lattice are *annotations* (attribution / regularity
//     support), not maliciousness evidence.
//   - Thresholds come from null quantiles generated by the same pipeline
//     (nullgen), and will be replaced by benign Neyman–Pearson quantiles once
//     the Q0 benign corpus is measured.
//   - Short series are refused rung by rung instead of being scored badly.
//
// Every metric that is not allowed at the series' rung is left nil.

const (
	IdleFloor   = 0.25 // idle gaps: IdleFloor·P ≤ g ≤ IdleCeil·P
	IdleCeil    = 3.0
	edgeMargin  = 0.10 // an edge percentile must sit ≥ 0.1·P inside the trim window
	sharpEdge   = 0.20 // E ≤ 0.2: sharp (uniform ≈ 0.11, triangular ≈ 0.28)
	triEdgeHigh = 0.36
)

// Timing is the v2 description of one event series.
type Timing struct {
	Events        int     `json:"events"`
	Gaps          int     `json:"gaps"`
	IdleGaps      int     `json:"idle_gaps"`
	PeriodSec     float64 `json:"period_sec"` // P = median gap (all gaps)
	TaskingBursts int     `json:"tasking_bursts"`
	MissedBeats   int     `json:"missed_beats,omitempty"` // gaps folded from ≈2P/3P
	Pauses        int     `json:"pauses"`
	Rung          int     `json:"rung"` // 0 refused, 10, 20, 30, 50
	Refused       string  `json:"refused,omitempty"`
	TailShort     bool    `json:"tail_short,omitempty"`

	CV    *float64 `json:"cv,omitempty"`
	CVRaw *float64 `json:"cv_unfolded,omitempty"`
	B     *float64 `json:"burstiness,omitempty"`
	An    *float64 `json:"burstiness_an,omitempty"`
	Rh    *float64 `json:"r_harmonic,omitempty"`
	Ra    *float64 `json:"r_absolute,omitempty"`
	F10   *float64 `json:"fano_10p,omitempty"`
	F50   *float64 `json:"fano_50p,omitempty"`
	Rho1  *float64 `json:"rho1,omitempty"`

	SleepSec *float64 `json:"sleep_upper_sec,omitempty"` // p98 of idle gaps
	LowerSec *float64 `json:"lower_edge_sec,omitempty"`  // p2 of idle gaps
	Spread   *float64 `json:"spread,omitempty"`          // 1 − p2/p98: relative spread, NOT the jitter setting
	Approx   bool     `json:"percentiles_approx,omitempty"`
	Eup      *float64 `json:"edge_up,omitempty"`
	Elo      *float64 `json:"edge_lo,omitempty"`

	Polarity     string   `json:"polarity_estimate,omitempty"`
	PolarityConf float64  `json:"polarity_confidence,omitempty"`
	JitterEst    *float64 `json:"jitter_est,omitempty"` // polarity-corrected; see JitterAssumes
	JitterAssume string   `json:"jitter_assumes,omitempty"`
	Lattice      bool     `json:"lattice,omitempty"`
	SizeBand     *float64 `json:"idle_size_band,omitempty"` // share of idle-poll sizes within ±max(8 B, 2 %) of their median
	SizeN        int      `json:"idle_size_n,omitempty"`
	Anchored     bool     `json:"anchored_scheduler,omitempty"`

	CaptureNeededHours float64 `json:"capture_needed_hours,omitempty"`
}

// Raw holds every metric computed without the refusal ladder (NaN when the
// series can't support it at all). nullgen uses it so the null tables come
// from exactly the pipeline the engine runs.
type Raw struct {
	N, Idle              int
	P                    float64
	Tasking, Pauses      int
	Missed               int
	CV, B, An            float64
	CVRaw                float64 // idle-window CV without harmonic folding
	idleEvents           []int   // indexes of events that end an idle (or folded) gap
	Rh, Ra               float64
	F10, F50             float64
	Rho1                 float64
	P1, P2, P10          float64
	P90, P98, P99        float64
	Spread               float64
	Eup, Elo             float64
	EupInside, EloInside bool
	LatticeR             float64
}

func nan() float64 { return math.NaN() }

// RawTiming computes all metrics for ascending event times (seconds).
func RawTiming(times []float64) Raw {
	r := Raw{CV: nan(), B: nan(), An: nan(), Rh: nan(), Ra: nan(), F10: nan(), F50: nan(), Rho1: nan(),
		P1: nan(), P2: nan(), P10: nan(), P90: nan(), P98: nan(), P99: nan(), Spread: nan(), Eup: nan(), Elo: nan(), LatticeR: nan()}
	if len(times) < 3 {
		return r
	}
	gaps := make([]float64, 0, len(times)-1)
	for i := 1; i < len(times); i++ {
		gaps = append(gaps, times[i]-times[i-1])
	}
	r.N = len(gaps)
	sg := Sorted(gaps)
	r.P = Quantile(sg, .5)
	if r.P <= 1e-9 {
		return r
	}
	// harmonic concentration over all gaps (spec Q2.2 T1)
	var cs, sn float64
	for _, g := range gaps {
		a := 2 * math.Pi * g / r.P
		cs += math.Cos(a)
		sn += math.Sin(a)
	}
	r.Rh = math.Hypot(cs, sn) / float64(len(gaps))
	// absolute phase over all events
	cs, sn = 0, 0
	for _, t := range times {
		a := 2 * math.Pi * (t - times[0]) / r.P
		cs += math.Cos(a)
		sn += math.Sin(a)
	}
	r.Ra = math.Hypot(cs, sn) / float64(len(times))

	// idle / tasking / pause split, in sequence order. Harmonic folding
	// first: a gap in [1.5P, 3.5P] is k = round(g/P) beats with k−1 missed
	// check-ins (loss, sleeping host, capture gap) and is counted as g/k.
	// (A ±15 % window around 2P/3P was tried first; it caught only the
	// centre of a doubled jittered gap — symmetric 30 % with 20 % missed
	// beats 0.60 vs 0.98 with round(g/P).)
	lo, hi := IdleFloor*r.P, IdleCeil*r.P
	var idle, raw []float64
	inBurst := false
	for gi, g := range gaps {
		if g >= lo && g <= hi {
			raw = append(raw, g)
		}
		if k := foldK(g, r.P); k > 1 {
			r.idleEvents = append(r.idleEvents, gi+1)
			idle = append(idle, g/float64(k))
			r.Missed += k - 1
			inBurst = false
			continue
		}
		switch {
		case g < lo:
			if !inBurst {
				r.Tasking++
				inBurst = true
			}
			continue
		case g > hi:
			r.Pauses++
		default:
			r.idleEvents = append(r.idleEvents, gi+1)
			idle = append(idle, g)
		}
		inBurst = false
	}
	r.Idle = len(idle)
	r.CVRaw = cvOf(raw)
	if r.Idle >= 2 {
		var m, v float64
		for _, g := range idle {
			m += g
		}
		m /= float64(len(idle))
		for _, g := range idle {
			v += (g - m) * (g - m)
		}
		sd := math.Sqrt(v / float64(len(idle)))
		r.CV = sd / m
		r.B = (sd - m) / (sd + m)
		r.An = KimJoAn(r.CV, len(idle))
		// lag-1 autocorrelation of idle gaps
		var num float64
		for i := 0; i+1 < len(idle); i++ {
			num += (idle[i] - m) * (idle[i+1] - m)
		}
		if v > 0 {
			r.Rho1 = num / v
		}
		// integer-second lattice concentration
		cs, sn = 0, 0
		for _, g := range idle {
			a := 2 * math.Pi * g
			cs += math.Cos(a)
			sn += math.Sin(a)
		}
		r.LatticeR = math.Hypot(cs, sn) / float64(len(idle))
		// percentiles and edges
		si := Sorted(idle)
		r.P1, r.P2, r.P10 = Quantile(si, .01), Quantile(si, .02), Quantile(si, .10)
		r.P90, r.P98, r.P99 = Quantile(si, .90), Quantile(si, .98), Quantile(si, .99)
		if r.P98 > 0 {
			r.Spread = 1 - r.P2/r.P98
		}
		if d := r.P90 - r.P10; d > 0 {
			r.Eup = (r.P99 - r.P90) / d
			r.Elo = (r.P10 - r.P1) / d
		}
		r.EupInside = hi-r.P99 >= edgeMargin*r.P
		r.EloInside = r.P1-lo >= edgeMargin*r.P
	}
	// multi-scale Fano on all events
	r.F10 = fano(times, 10*r.P)
	r.F50 = fano(times, 50*r.P)
	return r
}

func cvOf(x []float64) float64 {
	if len(x) < 2 {
		return nan()
	}
	var m, v float64
	for _, g := range x {
		m += g
	}
	m /= float64(len(x))
	for _, g := range x {
		v += (g - m) * (g - m)
	}
	if m <= 0 {
		return nan()
	}
	return math.Sqrt(v/float64(len(x))) / m
}

// foldK returns k = round(g/P) ∈ {2, 3} for gaps in [1.5P, 3.5P], else 1.
func foldK(g, p float64) int {
	if p <= 0 || g < 1.5*p || g > 3.5*p {
		return 1
	}
	return int(math.Round(g / p))
}

// KimJoAn is Kim & Jo's finite-n burstiness (arXiv 1604.01125):
// A_n = (√(n+1)·r − √(n−1)) / ((√(n+1) − 2)·r + √(n−1)), r = σ/μ.
func KimJoAn(cv float64, n int) float64 {
	if n < 2 || math.IsNaN(cv) {
		return nan()
	}
	a, b := math.Sqrt(float64(n+1)), math.Sqrt(float64(n-1))
	den := (a-2)*cv + b
	if den == 0 {
		return nan()
	}
	return (a*cv - b) / den
}

// fano is var/mean of event counts in consecutive windows of width w;
// NaN when fewer than 10 whole windows fit.
func fano(times []float64, w float64) float64 {
	if w <= 0 || len(times) < 2 {
		return nan()
	}
	span := times[len(times)-1] - times[0]
	m := int(span / w)
	if m < 10 {
		return nan()
	}
	counts := make([]float64, m)
	for _, t := range times {
		k := int((t - times[0]) / w)
		if k < m {
			counts[k]++
		}
	}
	var mean, v float64
	for _, c := range counts {
		mean += c
	}
	mean /= float64(m)
	if mean == 0 {
		return nan()
	}
	for _, c := range counts {
		v += (c - mean) * (c - mean)
	}
	return v / float64(m) / mean
}

func fp(x float64) *float64 {
	if math.IsNaN(x) || math.IsInf(x, 0) {
		return nil
	}
	v := math.Round(x*10000) / 10000
	return &v
}

// TimingParams carries context the series itself doesn't.
type TimingParams struct {
	CaptureEnd float64   // seconds on the same clock as times; 0 = unknown
	Sizes      []float64 // optional payload size per event (same order as times)
}

// AnalyzeTiming applies the refusal ladder (spec Q2.4) on top of RawTiming.
func AnalyzeTiming(times []float64, p TimingParams) Timing {
	sizes := p.Sizes
	if len(sizes) == len(times) {
		times, sizes = sortPairs(times, sizes)
	} else {
		times, sizes = Sorted(times), nil
	}
	r := RawTiming(times)
	t := Timing{Events: len(times), Gaps: r.N, IdleGaps: r.Idle, PeriodSec: round4(r.P), TaskingBursts: r.Tasking, Pauses: r.Pauses, MissedBeats: r.Missed}
	if p.CaptureEnd > 0 && len(times) > 0 && r.P > 0 && p.CaptureEnd-times[len(times)-1] < 3*r.P {
		// Annotation only: an active beacon's capture normally ends < 3P
		// after its last check-in (see review note on Q2.4).
		t.TailShort = true
	}
	switch n := r.Idle; {
	case n < 10:
		t.Refused = "too_few_events"
		t.CaptureNeededHours = neededHours(10, r)
		return t
	case n < 20:
		t.Rung = 10
	case n < 30:
		t.Rung = 20
	case n < 50:
		t.Rung = 30
	default:
		t.Rung = 50
	}
	t.CV, t.B, t.An, t.CVRaw = fp(r.CV), fp(r.B), fp(r.An), fp(r.CVRaw)
	if sizes != nil {
		var idleSizes []float64
		for _, i := range r.idleEvents {
			idleSizes = append(idleSizes, sizes[i])
		}
		if band, ok := SizeBand(idleSizes); ok {
			t.SizeBand = fp(band)
			t.SizeN = len(idleSizes)
		}
	}
	t.SleepSec, t.LowerSec, t.Spread = fp(r.P98), fp(r.P2), fp(r.Spread)
	t.Approx = t.Rung < 50
	if t.Rung < 50 {
		t.CaptureNeededHours = neededHours(map[int]int{10: 20, 20: 30, 30: 50}[t.Rung], r)
	}
	if t.Rung >= 20 {
		t.Rh, t.F10, t.F50, t.Rho1 = fp(r.Rh), fp(r.F10), fp(r.F50), fp(r.Rho1)
		// T5: an anchored grid plus random delay gives ρ₁ ≈ −0.5
		// (systemd RandomizedDelaySec, Defender, apt-daily); implant
		// jitter is independent per cycle (ρ₁ ≈ 0).
		if t.Rho1 != nil && *t.Rho1 <= -0.35 {
			t.Anchored = true
		}
	}
	if t.Rung >= 30 {
		t.Ra = fp(r.Ra)
		if r.EupInside {
			t.Eup = fp(r.Eup)
		}
		if r.EloInside {
			t.Elo = fp(r.Elo)
		}
		t.Polarity, t.PolarityConf = polarity(r, t.Rho1)
		t.JitterEst, t.JitterAssume = jitterFromSpread(r.Spread, t.Polarity)
		t.Lattice = r.P >= 2 && r.LatticeR >= 0.8 && (r.P98-r.P2) >= 2
		if t.Polarity == "anchored" {
			t.Anchored = true
		}
	}
	return t
}

func round4(x float64) float64 { return math.Round(x*10000) / 10000 }

func neededHours(idle int, r Raw) float64 {
	if r.P <= 0 || idle <= 0 {
		return 0
	}
	// idle gaps ≈ all gaps on a quiet beacon; P per gap
	return math.Round(float64(idle)*r.P/3600*100) / 100
}

// polarity reads the two edges (spec Q2.2 T7). Annotation only.
func polarity(r Raw, rho1 *float64) (string, float64) {
	up := r.EupInside && !math.IsNaN(r.Eup)
	lo := r.EloInside && !math.IsNaN(r.Elo)
	sharpUp := up && r.Eup <= sharpEdge
	sharpLo := lo && r.Elo <= sharpEdge
	tri := up && lo && r.Eup > sharpEdge && r.Eup <= triEdgeHigh && r.Elo > sharpEdge && r.Elo <= triEdgeHigh
	switch {
	case tri && rho1 != nil && *rho1 <= -0.35:
		return "anchored", 0.6
	case sharpUp && sharpLo:
		return "uniform", 0.5
	case sharpLo:
		return "lengthening-like", 0.6
	case sharpUp:
		return "shortening-like", 0.6
	}
	return "unknown", 0
}

// jitterFromSpread inverts spread under the assumed polarity (research §3):
// shortening s ≈ j; symmetric s ≈ 2j/(1+j); lengthening s ≈ j/(1+j).
func jitterFromSpread(s float64, pol string) (*float64, string) {
	if math.IsNaN(s) || s <= 0 || s >= 1 {
		return nil, ""
	}
	switch pol {
	case "shortening-like":
		return fp(s), "shortening: sleep·(1−U(0,j))"
	case "lengthening-like":
		return fp(s / (1 - s)), "lengthening: interval + U(0, j·interval)"
	case "uniform":
		return fp(s / (2 - s)), "symmetric: sleep·(1 ± U(0,j))"
	}
	return nil, ""
}

// Describe renders the annotations for a finding's detail text.
func (t Timing) Describe() string {
	if t.Refused != "" {
		return fmt.Sprintf("timing refused (%s): %d idle gaps; ≈%.1f h of capture needed", t.Refused, t.IdleGaps, t.CaptureNeededHours)
	}
	s := fmt.Sprintf("%d events, P=%.2fs, %d idle gaps (rung %d)", t.Events, t.PeriodSec, t.IdleGaps, t.Rung)
	if t.CV != nil {
		s += fmt.Sprintf(", CV %.2f", *t.CV)
	}
	if t.An != nil {
		s += fmt.Sprintf(", A_n %.2f", *t.An)
	}
	if t.Rh != nil {
		s += fmt.Sprintf(", R_h %.2f", *t.Rh)
	}
	if t.Spread != nil {
		approx := ""
		if t.Approx {
			approx = "≈"
		}
		s += fmt.Sprintf(", relative spread %s%.2f", approx, *t.Spread)
	}
	// Shape wording only (v8a review #6): edge shape is not framework
	// polarity until measured; the jitter estimate stays in JSON.
	switch t.Polarity {
	case "shortening-like":
		s += ", upper edge sharp"
		if t.SleepSec != nil {
			s += fmt.Sprintf(" (≈%.1fs)", *t.SleepSec)
		}
	case "lengthening-like":
		s += ", lower edge sharp"
		if t.LowerSec != nil {
			s += fmt.Sprintf(" (≈%.1fs)", *t.LowerSec)
		}
	case "uniform":
		s += ", both edges sharp"
	case "anchored":
		s += ", triangular edges"
	}
	if t.Lattice {
		s += ", integer-second lattice"
	}
	if sh := SchedulerShape(t); sh != "" {
		s += ", shape matches " + sh
	}
	if t.Anchored {
		s += ", anchored-scheduler shape (ρ₁ ≈ −0.5)"
	}
	if t.TaskingBursts > 0 {
		s += fmt.Sprintf(", %d tasking bursts", t.TaskingBursts)
	}
	if t.Pauses > 0 {
		s += fmt.Sprintf(", %d pauses", t.Pauses)
	}
	if t.MissedBeats > 0 {
		s += fmt.Sprintf(", %d missed check-ins folded", t.MissedBeats)
	}
	if t.Gaps < 60 && t.Spread != nil && *t.Spread > 0.5 {
		// v9 Phase 0.2: high-jitter series need more events for full power.
		s += fmt.Sprintf("; judged on %d events with high spread — ≥ 60 events needed for full power", t.Events)
	}
	return s
}

// ProvisionalNull is the benign stand-in until Q0's benign corpus supplies
// Neyman–Pearson quantiles: a gamma(k=4) renewal process (CV ≈ 0.5) — the
// most regular plausible benign renewal traffic (chatty sync clients),
// generated through the same folding pipeline. v8a used gamma(k=2), which
// let gamma(4)-like benign traffic through 77 % of the time at 200 events
// (stress finding 2). An absolute CV ceiling was tried instead and rejected:
// folding lowers benign CV too, so a fixed ceiling still passed 16 %.
const ProvisionalNull = NullGamma4

// quantileAt returns the null lower-tail quantile at any alpha in
// [1e-4, 1e-2], log-linearly interpolated between the tabulated points.
func quantileAt(metric string, n int, alpha float64) float64 {
	as := []float64{1e-2, 1e-3, 1e-4}
	alpha = math.Max(1e-4, math.Min(1e-2, alpha))
	for i := 0; i+1 < len(as); i++ {
		if alpha <= as[i] && alpha >= as[i+1] {
			a := NullQuantile(ProvisionalNull, metric, n, false, as[i])
			b := NullQuantile(ProvisionalNull, metric, n, false, as[i+1])
			t := (math.Log10(as[i]) - math.Log10(alpha)) / (math.Log10(as[i]) - math.Log10(as[i+1]))
			return a*(1-t) + b*t
		}
	}
	return NullQuantile(ProvisionalNull, metric, n, false, alpha)
}

// tailScore maps a CV onto evidence against its own null: 0 above the
// alpha=2e-2… quantile ladder used below, 0.5 / 0.75 / 1 at the Bonferroni-
// corrected 1e-2 / 1e-3 / 1e-4 points, linear in between.
func tailScore(metric string, n int, cv float64, looks int) (float64, [3]float64) {
	k := float64(looks)
	q := [3]float64{quantileAt(metric, n, 1e-2/k), quantileAt(metric, n, 1e-3/k), quantileAt(metric, n, 1e-4/k)}
	if math.IsNaN(cv) || math.IsNaN(q[0]) || math.IsNaN(q[2]) || cv > q[0] {
		return 0, q
	}
	switch {
	case cv <= q[2]:
		return 1, q
	case cv <= q[1]:
		return 0.75 + 0.25*(q[1]-cv)/(q[1]-q[2]), q
	}
	return 0.5 + 0.25*(q[0]-cv)/(q[0]-q[1]), q
}

// SizeBandMin is the idle-poll size-band share that counts as "stable".
const SizeBandMin = 0.8

// SizeBand is the share of sizes within ±max(8 B, 2 % of median) of their
// median; ok=false below 10 samples.
func SizeBand(sizes []float64) (float64, bool) {
	if len(sizes) < 10 {
		return 0, false
	}
	med := Quantile(Sorted(sizes), .5)
	tol := math.Max(8, 0.02*med)
	in := 0
	for _, x := range sizes {
		if math.Abs(x-med) <= tol {
			in++
		}
	}
	return float64(in) / float64(len(sizes)), true
}

// DispersionEvidence scores how far the idle-gap CV sits below the null's
// lower tail at this gap count (the only timing quantity used as
// maliciousness evidence, spec Q2.5). Two looks — harmonically folded CV
// (robust to missed check-ins) and unfolded CV (keeps high-jitter power) —
// each against its own generated null, Bonferroni-corrected (α/2), best wins.
func (t Timing) DispersionEvidence() (float64, string) {
	if t.Refused != "" || t.CV == nil {
		return 0, ""
	}
	n := t.Gaps
	sf, qf := tailScore("cv", n, *t.CV, 2)
	sr, qr := 0.0, [3]float64{}
	if t.CVRaw != nil {
		sr, qr = tailScore("cv_raw", n, *t.CVRaw, 2)
	}
	if sf <= 0 && sr <= 0 {
		return 0, ""
	}
	stable := t.SizeBand != nil && *t.SizeBand >= SizeBandMin
	boost := func(s float64, d string) (float64, string) {
		// Size look (v9 Phase 0.2): a stable idle-poll size buys one decade
		// of timing significance (q1e-2 → the q1e-3 evidence level). Worst
		// case — benign traffic with fixed sizes — the FP rate is bounded
		// by the timing look's q1e-2 tail (Bonferroni α/2 per look).
		if stable && s >= 0.5 {
			return math.Min(1, s+0.25), d + fmt.Sprintf("; stable idle-poll size (%.0f%% within ±max(8 B, 2%%) of the median) adds one decade of significance", *t.SizeBand*100)
		}
		return s, d
	}
	if sr > sf {
		return boost(sr, fmt.Sprintf("idle-gap CV %.2f (unfolded) vs %s null at %d gaps (Bonferroni q1e-2 %.2f, q1e-4 %.2f)", *t.CVRaw, ProvisionalNull, n, qr[0], qr[2]))
	}
	return boost(sf, fmt.Sprintf("idle-gap CV %.2f (missed beats folded) vs %s null at %d gaps (Bonferroni q1e-2 %.2f, q1e-4 %.2f)", *t.CV, ProvisionalNull, n, qf[0], qf[2]))
}

// SchedulerShape names a benign scheduler whose cadence the series matches
// (annotation only, v9 Phase 1.3; research §5 scheduler models). Matching a
// scheduler doesn't clear a series — it explains why timing alone is weak.
func SchedulerShape(t Timing) string {
	p := t.PeriodSec
	spread := 0.0
	if t.Spread != nil {
		spread = *t.Spread
	}
	switch {
	case p >= 5400 && p <= 7200:
		return "Windows Group Policy refresh (90 + 0–30 min)"
	case p >= 600 && p <= 1200 && spread >= 0.3:
		return "Jamf check-in (15 ± 5 min)"
	case p >= 0.8*79200 && p <= 79200:
		return "WSUS detection cycle (22 h × 80–100 %)"
	case spread <= 0.05 && p >= 60:
		for k := 64.0; k <= 1024; k *= 2 {
			if p >= k && p <= 1.03*k {
				return fmt.Sprintf("NTP/chrony poll (%.0f s)", k)
			}
		}
	}
	return ""
}

// GapShape names a benign scheduler from the raw event times when the
// pattern lives in the gap sequence rather than a single period (v9c, D2):
//
//   - MDM check-in ladder: after enrolment or a reboot, ~3 min check-ins
//     (≥ 3), then ~15 min (≥ 5), then ~8 h, with push-triggered syncs
//     in between; ≥ 60 % of gaps must sit on a rung.
//   - Browser updater: ~5 h + U(0, 60 s), sometimes ~6 h; ≥ 70 % of gaps on
//     those two rungs, ≥ 2 on the 5 h one.
//
// Like SchedulerShape this only explains why timing alone is weak.
func GapShape(times []float64) string {
	if len(times) < 4 {
		return ""
	}
	times = Sorted(times)
	gaps := make([]float64, 0, len(times)-1)
	for i := 1; i < len(times); i++ {
		gaps = append(gaps, times[i]-times[i-1])
	}
	near := func(g, c, tol float64) bool { return math.Abs(g-c) <= tol }
	var m3, m15, h8, h5, h6 int
	for _, g := range gaps {
		switch {
		case near(g, 180, 36):
			m3++
		case near(g, 900, 180):
			m15++
		case near(g, 28800, 2880):
			h8++
		case g >= 17990 && g <= 18080:
			h5++
		case g >= 21590 && g <= 21680:
			h6++
		}
	}
	n := float64(len(gaps))
	if m3 >= 3 && m15 >= 5 && float64(m3+m15+h8) >= 0.6*n {
		return "MDM check-in ladder (3 min, 15 min, then ~8 h)"
	}
	if h5 >= 2 && float64(h5+h6) >= 0.7*n {
		return "browser updater (5 h + U(0, 60 s), sometimes 6 h)"
	}
	return ""
}
